package com.mo.economy_system.common.territory;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.Test;
class TerritoryInviteRequestServiceTest {private static TerritoryInviteRequestService service(UUID owner,UUID target,UUID land,TerritoryInviteStore store,TerritoryInviteRequestService.Ids ids){return new TerritoryInviteRequestService(id->Optional.of(new TerritoryInviteRequestService.Territory(land,owner,"land",Set.of())),id->Optional.of(new TerritoryInviteRequestService.Player(target,"target")),store,new TerritoryInviteRateLimiter(),ids);}
 @Test void successUsesServerIdentityAndTicks(){UUID o=UUID.randomUUID(),t=UUID.randomUUID(),l=UUID.randomUUID(),id=UUID.randomUUID();var out=service(o,t,l,new TerritoryInviteStore(),()->id).create(o,"owner",l,t,10);assertEquals(TerritoryInviteResult.SUCCESS,out.result());assertEquals(id,out.invite().inviteId());assertEquals("target",out.invite().targetPlayerName());assertEquals(1210,out.invite().expiresTick());}
 @Test void collisionRetriesAndEightFailWithoutOverwrite(){UUID o=UUID.randomUUID(),t=UUID.randomUUID(),l=UUID.randomUUID(),collision=UUID.randomUUID(),fresh=UUID.randomUUID();TerritoryInviteStore store=new TerritoryInviteStore();UUID otherOwner=UUID.randomUUID();store.put(new TerritoryInvite(collision,UUID.randomUUID(),otherOwner,otherOwner,UUID.randomUUID(),"x","x","x",0,10),0);AtomicInteger n=new AtomicInteger();assertEquals(TerritoryInviteResult.SUCCESS,service(o,t,l,store,()->n.getAndIncrement()==0?collision:fresh).create(o,"owner",l,t,0).result());assertTrue(store.find(collision,0).isPresent());assertEquals(TerritoryInviteResult.CREATE_FAILED,service(o,UUID.randomUUID(),UUID.randomUUID(),store,()->collision).create(o,"owner",l,t,0).result());}
 @Test void validatesRepositoryAndDirectoryContracts(){UUID o=UUID.randomUUID(),t=UUID.randomUUID(),l=UUID.randomUUID();var badTerritory=new TerritoryInviteRequestService(id->Optional.of(new TerritoryInviteRequestService.Territory(UUID.randomUUID(),o,"x",Set.of())),id->Optional.empty(),new TerritoryInviteStore(),new TerritoryInviteRateLimiter(),UUID::randomUUID);assertEquals(TerritoryInviteResult.CREATE_FAILED,badTerritory.create(o,"owner",l,t,0).result());var badPlayer=new TerritoryInviteRequestService(id->Optional.of(new TerritoryInviteRequestService.Territory(l,o,"x",Set.of())),id->Optional.of(new TerritoryInviteRequestService.Player(UUID.randomUUID(),"x")),new TerritoryInviteStore(),new TerritoryInviteRateLimiter(),UUID::randomUUID);assertEquals(TerritoryInviteResult.CREATE_FAILED,badPlayer.create(o,"owner",l,t,0).result());}
 @Test void businessFailuresAreDistinct(){UUID o=UUID.randomUUID(),t=UUID.randomUUID(),l=UUID.randomUUID();var missing=new TerritoryInviteRequestService(id->Optional.empty(),id->Optional.empty(),new TerritoryInviteStore(),new TerritoryInviteRateLimiter(),UUID::randomUUID);assertEquals(TerritoryInviteResult.TERRITORY_NOT_FOUND,missing.create(o,"owner",l,t,0).result());var offline=new TerritoryInviteRequestService(id->Optional.of(new TerritoryInviteRequestService.Territory(l,o,"x",Set.of())),id->Optional.empty(),new TerritoryInviteStore(),new TerritoryInviteRateLimiter(),UUID::randomUUID);assertEquals(TerritoryInviteResult.TARGET_OFFLINE,offline.create(o,"owner",l,t,0).result());assertEquals(TerritoryInviteResult.NO_PERMISSION,offline.create(UUID.randomUUID(),"x",l,t,0).result());assertEquals(TerritoryInviteResult.CANNOT_INVITE_SELF,offline.create(o,"owner",l,o,0).result());var member=new TerritoryInviteRequestService(id->Optional.of(new TerritoryInviteRequestService.Territory(l,o,"x",Set.of(t))),id->Optional.empty(),new TerritoryInviteStore(),new TerritoryInviteRateLimiter(),UUID::randomUUID);assertEquals(TerritoryInviteResult.ALREADY_MEMBER,member.create(o,"owner",l,t,0).result());}
 @Test void diagnosticsCannotChangeFailureAndErrorsEscape(){UUID o=UUID.randomUUID(),t=UUID.randomUUID(),l=UUID.randomUUID();AtomicReference<String> stage=new AtomicReference<>();var s=new TerritoryInviteRequestService(id->{throw new IllegalStateException();},id->Optional.empty(),new TerritoryInviteStore(),new TerritoryInviteRateLimiter(),UUID::randomUUID,(a,b,c,d,e)->{stage.set(a);throw new IllegalStateException();},1200);assertEquals(TerritoryInviteResult.CREATE_FAILED,s.create(o,"owner",l,t,0).result());assertEquals("repository",stage.get());var error=new TerritoryInviteRequestService(id->{throw new AssertionError();},id->Optional.empty(),new TerritoryInviteStore(),new TerritoryInviteRateLimiter(),UUID::randomUUID);assertThrows(AssertionError.class,()->error.create(o,"owner",l,t,0));}
 @Test void constructorsAndModelsValidate(){assertThrows(IllegalArgumentException.class,()->new TerritoryInviteRateLimiter(0));assertThrows(IllegalArgumentException.class,()->new TerritoryInviteRequestService(id->Optional.empty(),id->Optional.empty(),new TerritoryInviteStore(),new TerritoryInviteRateLimiter(),UUID::randomUUID,(a,b,c,d,e)->{},0));UUID o=UUID.randomUUID();assertThrows(IllegalArgumentException.class,()->new TerritoryInviteRequestService.Territory(UUID.randomUUID(),o,"x",Set.of(o)));}}
